def HeapProbe.mirror (x_1 : obj) : obj :=
  case x_1 : obj of
  HeapProbe.Tree.leaf →
    ret x_1
  HeapProbe.Tree.branch →
    let x_2 : obj := proj[0] x_1;
    let x_3 : obj := proj[1] x_1;
    block_4 (x_5 : tobj) (x_6 : u8) :=
      let x_7 : obj := HeapProbe.mirror x_3;
      let x_8 : obj := HeapProbe.mirror x_2;
      block_9 (x_10 : obj) :=
        ret x_10;
      case x_6 : u8 of
      Bool.false →
        set x_5[1] := x_8;
        set x_5[0] := x_7;
        jmp block_9 x_5
      Bool.true →
        let x_11 : obj := ctor_1[HeapProbe.Tree.branch] x_7 x_8;
        jmp block_9 x_11;
    let x_12 : u8 := isShared x_1;
    case x_12 : u8 of
    Bool.false →
      jmp block_4 x_1 x_12
    Bool.true →
      inc x_3;
      inc x_2;
      dec x_1;
      jmp block_4 ◾ x_12
